K="sudo kubectl --kubeconfig=/etc/kubernetes/admin.conf"
snap(){ { date -Is; echo "[$1]"; for Q in 'fds_evaluation_error_total' 'transaction_save_success_total' 'transaction_save_failure_total' 'fds_evaluated_total' 'up{job=~"transaction-api|fds-engine"}' 'ALERTS{alertstate=~"firing|pending"}'; do echo "## $Q"; curl -s -m 10 localhost:19093/api/v1/query --data-urlencode "query=$Q" | python3 -c 'import sys,json;[print(r["metric"].get("pod") or r["metric"].get("instance") or r["metric"].get("alertname") or "-",r["metric"].get("job",""),r["value"][1]) for r in json.load(sys.stdin)["data"]["result"]]'; done; $K -n fds-app get pods -o custom-columns=POD:.metadata.name,NODE:.spec.nodeName,READY:.status.containerStatuses[0].ready,RESTARTS:.status.containerStatuses[0].restartCount; } 2>&1 | tee -a $D/metrics.log; }
